class TerminalFrameAck(TypedDict):
    """Consumer acknowledgement: every byte before ack_seq was processed. Direction: client to platform to executor."""
    type: Literal["ack"]
    session_id: NotRequired[str]
    ack_seq: int

class TerminalFrameAttach(TypedDict):
    """First and only first frame a client sends on the relay socket (any other first frame is answered with error terminal_internal_error). Not sent on the host socket: terminal.attach carries the same fields as params. from_seq is the first output byte the client still needs and ack_seq the last byte it has consumed; from_seq above latest_seq is answered with error terminal_invalid_frame. Exactly one attachment per terminal at a time: while one is attached, another attach (can_write false included) is answered with error terminal_writer_busy and the socket is closed. Direction: client to platform."""
    type: Literal["attach"]
    session_id: NotRequired[str]
    rows: NotRequired[int]
    cols: NotRequired[int]
    from_seq: NotRequired[int]
    ack_seq: NotRequired[int]
    can_write: NotRequired[bool]

class TerminalFrameAttached(TypedDict):
    """Answer to an attach; on the host socket the executor writes it first, before answering terminal.attach. writer_epoch increases on every attach of the terminal (attempts that fail may consume a value too) and fences input. earliest_seq is omitted when 0. Output from from_seq follows (preceded by gap when from_seq < earliest_seq). Direction: executor to platform to client."""
    type: Literal["attached"]
    session_id: NotRequired[str]
    rows: int
    cols: int
    pid: int
    writer_epoch: int
    can_write: bool
    earliest_seq: NotRequired[int]
    latest_seq: int

class TerminalFrameClose(TypedDict):
    """Close the terminal (the PTY ends, not only this attachment); answered with closed. Closing the socket instead only detaches. Direction: client to platform to executor."""
    type: Literal["close"]
    session_id: NotRequired[str]
    reason: NotRequired[str]

class TerminalFrameClosed(TypedDict):
    """The terminal was closed (close frame or terminal.close); the socket closes after it. Direction: executor or platform to client."""
    type: Literal["closed"]
    session_id: NotRequired[str]
    reason: NotRequired[str]

class TerminalFrameError(TypedDict):
    """A refused frame or attach. After terminal_writer_busy, terminal_invalid_frame on attach, or terminal_internal_error the socket is closed; other errors leave the attachment open. Peers must also tolerate a socket that ends without a close frame. Direction: executor or platform to client."""
    type: Literal["error"]
    session_id: NotRequired[str]
    code: TerminalErrorCode
    message: str

class TerminalFrameExit(TypedDict):
    """The PTY process exited; end_seq is the offset after its last output byte. The socket closes after it. Direction: executor to platform to client."""
    type: Literal["exit"]
    session_id: NotRequired[str]
    end_seq: int
    exit_code: NotRequired[int | None]
    exit_reason: NotRequired[str]
    exited: Literal[true]

class TerminalFrameGap(TypedDict):
    """Sent before output when the requested from_seq fell out of the ring buffer (the reference executor keeps 1 MiB): output resumes at earliest_seq. Direction: executor to platform to client."""
    type: Literal["gap"]
    session_id: NotRequired[str]
    earliest_seq: int
    latest_seq: int
    truncated: Literal[true]

class TerminalFrameInput(TypedDict):
    """Bytes for the PTY, base64 in data. Accepted only from the attachment holding the writer lease; writer_epoch, when present, must equal the lease's epoch (attached.writer_epoch) or the frame is dropped with error terminal_stale_writer. Clients send the epoch of their attached frame. Direction: client to platform to executor."""
    type: Literal["input"]
    session_id: NotRequired[str]
    data: str
    writer_epoch: NotRequired[int]

class TerminalFrameOutput(TypedDict):
    """PTY output bytes [from_seq, end_seq), base64 (standard, padded) in data. Sequence numbers are byte offsets of the PTY output since the PTY was created; chunks are contiguous and at most 32768 bytes. from_seq is omitted when 0. The producer stops sending after a window of unacknowledged bytes until the consumer acks, so consumers ack every end_seq they processed. Direction: executor to platform to client."""
    type: Literal["output"]
    session_id: NotRequired[str]
    from_seq: NotRequired[int]
    end_seq: int
    data: str

class TerminalFrameResize(TypedDict):
    """Resize the PTY; answered with resized. Direction: client to platform to executor."""
    type: Literal["resize"]
    session_id: NotRequired[str]
    rows: int
    cols: int

class TerminalFrameResized(TypedDict):
    """The PTY size after a resize. Direction: executor to platform to client."""
    type: Literal["resized"]
    session_id: NotRequired[str]
    rows: int
    cols: int

class TerminalFrameType(str, Enum):
    """Frame discriminator. Receivers ignore frames of unknown type except as noted (the reference relay answers an unknown type with error terminal_invalid_frame)."""
