class WorkspacePendingRestore(TypedDict):
    """GET …/restore 200 answer: the backup a recreated machine restores before executor.register. The executor downloads GET …/backups/{backup_id}/archive, checks length = size_bytes and sha256 = digest before writing anything, restores it (WorkspaceArchive), then posts the result. Failures are retried with backoff before registering; when giving up it posts state failed."""
